:root {
  --bg: #f4f1ea;
  --card-bg: #ffffff;
  --text: #1e1e2f;
  --muted: #5a5a72;
  --accent: #3b5bdb;
  --accent-hover: #2f4ac0;
  --accent-pressed: #243b9e;
  --border: #d1cbc0;
  --focus: #f59f00;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
  padding: 32px;
  width: 100%;
  max-width: 640px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 1rem;
  color: var(--muted);
  margin-top: -12px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

textarea {
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  padding: 14px;
  border: 2px solid var(--border);
  border-radius: 8px;
  resize: vertical;
  min-height: 160px;
  color: var(--text);
  background: #faf9f6;
  transition: border-color 0.15s ease;
}

textarea:hover {
  border-color: var(--muted);
}

textarea:focus {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  background: #faf9f6;
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 8px;
  text-align: center;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.stat-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-weight: 600;
}

button {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  background: var(--accent);
  color: #ffffff;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease;
  align-self: flex-start;
}

button:hover {
  background: var(--accent-hover);
}

button:active {
  background: var(--accent-pressed);
  transform: scale(0.97);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }

  .stats {
    grid-template-columns: repeat(2, 1fr);
  }

  h1 {
    font-size: 1.4rem;
  }
}

(function () {
  'use strict';

  var textInput = document.getElementById('text-input');
  var wordCountEl = document.getElementById('word-count');
  var charCountEl = document.getElementById('char-count');
  var sentenceCountEl = document.getElementById('sentence-count');
  var readingTimeEl = document.getElementById('reading-time');
  var clearBtn = document.getElementById('clear-btn');

  var WORDS_PER_MINUTE = 200;

  function countWords(text) {
    var trimmed = text.trim();
    if (!trimmed) return 0;
    return trimmed.split(/\s+/).length;
  }

  function countSentences(text) {
    var trimmed = text.trim();
    if (!trimmed) return 0;
    var matches = trimmed.match(/[^.!?]+[.!?]+/g);
    var count = matches ? matches.length : 0;
    // If there is remaining text without terminal punctuation, count it as a sentence
    var cleaned = trimmed.replace(/[^.!?]+[.!?]+/g, '').trim();
    if (cleaned.length > 0) count += 1;
    return count;
  }

  function formatReadingTime(words) {
    if (words === 0) return '0s';
    var minutes = words / WORDS_PER_MINUTE;
    if (minutes < 1) {
      var seconds = Math.round(minutes * 60);
      return seconds + 's';
    }
    var mins = Math.floor(minutes);
    var secs = Math.round((minutes - mins) * 60);
    if (secs === 60) {
      mins += 1;
      secs = 0;
    }
    return mins + 'm ' + secs + 's';
  }

  function updateCounts() {
    var text = textInput.value;
    var words = countWords(text);
    var chars = text.length;
    var sentences = countSentences(text);

    wordCountEl.textContent = words;
    charCountEl.textContent = chars;
    sentenceCountEl.textContent = sentences;
    readingTimeEl.textContent = formatReadingTime(words);
  }

  function clearText() {
    textInput.value = '';
    updateCounts();
    textInput.focus();
  }

  textInput.addEventListener('input', updateCounts);
  clearBtn.addEventListener('click', clearText);

  // Initialize counts on load
  updateCounts();
})();
